    receive() external payable {}
    function run(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) public {
        uint64 numberBefore = c.number(); if (__ESBMC_reverted()) return;
        uint64 tsBefore = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 feeBefore = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 hashBefore = c.hash(); if (__ESBMC_reverted()) return;
        uint64 seqBefore = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 batcherBefore = c.batcherHash(); if (__ESBMC_reverted()) return;
