pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) internal {
        uint64 numberBefore;
        try c.number() returns (uint64 __r) { numberBefore = __r; } catch { return; }
        uint64 tsBefore;
        try c.timestamp() returns (uint64 __r) { tsBefore = __r; } catch { return; }
        uint256 feeBefore;
        try c.basefee() returns (uint256 __r) { feeBefore = __r; } catch { return; }
        bytes32 hashBefore;
        try c.hash() returns (bytes32 __r) { hashBefore = __r; } catch { return; }
        uint64 seqBefore;
        try c.sequenceNumber() returns (uint64 __r) { seqBefore = __r; } catch { return; }
        bytes32 batcherBefore;
        try c.batcherHash() returns (bytes32 __r) { batcherBefore = __r; } catch { return; }
        uint256 overheadBefore;
        try c.l1FeeOverhead() returns (uint256 __r) { overheadBefore = __r; } catch { return; }
        uint256 scalarBefore;
        try c.l1FeeScalar() returns (uint256 __r) { scalarBefore = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(n, t, f, h, s, b, o, sc) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted &&
            c.number() == numberBefore &&
            c.timestamp() == tsBefore &&
            c.basefee() == feeBefore &&
            c.hash() == hashBefore &&
            c.sequenceNumber() == seqBefore &&
            c.batcherHash() == batcherBefore &&
            c.l1FeeOverhead() == overheadBefore &&
            c.l1FeeScalar() == scalarBefore);
    }

    function testFuzz_run(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) public {
        _run(n, t, f, h, s, b, o, sc);
    }

    receive() external payable {}
}
